import{_ as t,b as l,c as o,g as r}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"自然语言处理中的深度学习","description":"","frontmatter":{"title":"自然语言处理中的深度学习","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/24.md","filePath":"articles/ai/books/ai-modern-approach/24.md"}'),n={name:"articles/ai/books/ai-modern-approach/24.md"};function e(s,i,a,d,g,p){return l(),o("div",null,[...i[0]||(i[0]=[r('<p>第 24 章介绍深度学习在自然语言处理中的应用，核心是通过分布式表示和神经网络架构处理文本数据。重点包括：</p><h2 id="词向量" tabindex="-1">词向量</h2><ul><li><strong>Word2Vec、GloVe</strong>：将词映射为稠密向量</li><li>词向量算术性质（如 king - man + woman ≈ queen）</li><li>余弦相似度衡量语义相近性</li></ul><h2 id="序列模型" tabindex="-1">序列模型</h2><ul><li><strong>RNN</strong>：处理变长序列，隐藏状态递推更新</li><li><strong>双向 RNN（BiRNN）</strong>：同时利用前后文信息，适用于分类任务但不适用于语言模型</li><li><strong>LSTM / GRU</strong>：缓解梯度消失，捕获长距离依赖</li></ul><h2 id="注意力机制" tabindex="-1">注意力机制</h2><ul><li>核心公式：αᵢ = exp(q·kᵢ) / Σⱼ exp(q·kⱼ)，输出 = Σᵢ αᵢ vᵢ</li><li>在机器翻译中：查询来自解码器，键和值来自编码器</li><li>解决 Seq2Seq 长句信息瓶颈问题</li></ul><h2 id="transformer" tabindex="-1">Transformer</h2><ul><li><strong>自注意力（Self-Attention）</strong>：序列内各位置相互关注</li><li>多头注意力、位置编码、前馈网络</li><li>并行计算优势，对长距离依赖建模能力强</li></ul><h2 id="预训练语言模型" tabindex="-1">预训练语言模型</h2><ul><li><strong>BERT</strong>：双向上下文，掩码语言模型（MLM）、下一句预测（NSP）</li><li><strong>GPT</strong>：单向自回归语言模型，适合生成任务</li><li>预训练 + 微调范式，RoBERTa 等改进</li></ul><h2 id="应用任务" tabindex="-1">应用任务</h2><ul><li><strong>文本分类</strong>：词嵌入 + LSTM + 全连接层</li><li><strong>机器翻译</strong>：编码器-解码器 + 注意力 / Transformer</li><li><strong>命名实体识别（NER）</strong>：BiLSTM-CRF，span-based F1 评价</li><li><strong>问答系统</strong>：检索式 vs 生成式，BERT 微调预测答案起止位置</li></ul>',13)])])}const u=t(n,[["render",e]]);export{c as __pageData,u as default};
